const IN=[["cash","Cash today (\u20ac)",120000],["mrr","MRR today (\u20ac)",8000],["growth","MRR growth / month (%)",8],["churn","Churn / month (%)",3],
["cogs","Cost of sales (% of revenue)",22],["payroll","Payroll / month (\u20ac)",21000],["other","Other costs / month (\u20ac)",4500],
["cac","CAC per customer (\u20ac)",320],["arpu","ARPU / month (\u20ac)",42],["months","Months to project",18]];
const S={};IN.forEach(([k,,v])=>S[k]=v);
const eur=n=>(n<0?"-":"")+"\u20ac"+Math.abs(Math.round(n)).toLocaleString();
inputs.innerHTML=IN.map(([k,l,v])=>`<label>${l}<input type=number id=f_${k} value=${v}></label>`).join('');
IN.forEach(([k])=>document.getElementById('f_'+k).oninput=e=>{S[k]=+e.target.value||0;run()});
function run(){
 let cash=S.cash,mrr=S.mrr,rows=[],runway=null;
 for(let m=1;m<=Math.max(1,Math.min(S.months,120));m++){
  mrr=mrr*(1+S.growth/100)*(1-S.churn/100);
  const rev=mrr,cost=rev*S.cogs/100+S.payroll+S.other,burn=cost-rev;
  cash-=burn;rows.push({m,mrr:rev,cost,burn,cash});
  if(cash<0&&runway===null)runway=m;}
 const ltv=S.arpu*(S.churn?100/S.churn:0)*(1-S.cogs/100),ratio=S.cac?ltv/S.cac:0,payback=S.arpu?S.cac/(S.arpu*(1-S.cogs/100)):0;
 tiles.innerHTML=[[runway?runway+" months":"profitable","Runway"],[eur(ltv),"LTV"],[ratio.toFixed(1)+"x","LTV / CAC"],[payback.toFixed(1)+" mo","CAC payback"],[eur(rows.at(-1).mrr),"MRR at end"]]
  .map(([v,l])=>`<div class=tile><b>${v}</b><span>${l}</span></div>`).join('');
 tbl.innerHTML="<tr><th>Month</th><th>MRR</th><th>Costs</th><th>Burn</th><th>Cash</th></tr>"+rows.map(r=>`<tr class="${r.cash<0?'neg':''}"><td>${r.m}</td><td>${eur(r.mrr)}</td><td>${eur(r.cost)}</td><td>${eur(r.burn)}</td><td>${eur(r.cash)}</td></tr>`).join('');
 const mx=Math.max(...rows.map(r=>r.cash),S.cash,0),mn=Math.min(...rows.map(r=>r.cash),0),y=v=>200-((v-mn)/((mx-mn)||1))*180;
 chart.innerHTML=`<line x1=30 x2=630 y1=${y(0)} y2=${y(0)} stroke="currentColor" opacity="0.3" />`+
  `<polyline fill=none stroke=#0071e3 stroke-width=2.5 points="${rows.map((r,i)=>`${30+i*(600/Math.max(rows.length-1,1))},${y(r.cash)}`).join(' ')}"/>`+
  `<text x=4 y=${y(mx)+4} font-size="11" fill="currentColor" opacity="0.6">${eur(mx)}</text>`;
}
run();

